def compute(vars):
    total_restricted = vars["v2"]
    insurance_programs = vars["v1"]

    if total_restricted == 0:
        return None

    value = insurance_programs / total_restricted * 100
    return {
        "value": value,
        "trace": {
            "insurance_programs": insurance_programs,
            "total_restricted": total_restricted,
            "ratio": insurance_programs / total_restricted,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
